// Given: small helpers shared by the demos. Do not edit this file.

/** Appends a canvas of the given CSS height that fills the container's width. */
export function mountCanvas(container: HTMLElement, height: number): HTMLCanvasElement {
  const canvas = document.createElement("canvas");
  canvas.style.cssText = `display:block;width:100%;height:${height}px;margin-top:16px;border-radius:8px`;
  container.appendChild(canvas);
  return canvas;
}

/** A friendly box for an error, especially a "TODO: Exercise N" stub. */
export function todoBox(e: unknown): HTMLElement {
  const msg = e instanceof Error ? e.message : String(e);
  const box = document.createElement("pre");
  box.className = "todo";
  box.textContent = msg.startsWith("TODO")
    ? `This part needs code you have not written yet:\n\n  ${msg}\n\nRun the tests for that exercise, then reload.`
    : `The demo stopped with an error:\n\n  ${msg}`;
  console.error(e);
  return box;
}
